style.css:
@-moz-document domain("roblox.com") {
/* =========================
   SAYA-INSPIRED SIMPLE THEME
========================= */

/* Background */
body {
    background:
        linear-gradient(
            rgba(0,0,0,0.75),
            rgba(0,0,0,0.75)
        ),
        url("https://files.catbox.moe/f435i9.jpg")
        center center fixed !important;

    background-size: cover !important;
}

/* Soft dark overlay (keeps readability) */
body::after {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    pointer-events: none;

    background:
        radial-gradient(
            circle,
            transparent 35%,
            rgba(0,0,0,0.85) 100%
        );

    z-index: 9999;
}

/* Base text */
* {
    color: #e0c7c0 !important;
}

/* Top bar */
.navbar,
.header,
.header-container {
    background: rgba(10, 0, 0, 0.85) !important;
    border-bottom: 1px solid rgba(120, 40, 40, 0.35) !important;
}

/* Sidebar */
nav,
.left-col,
.rbx-left-col,
#navigation {
    background: rgba(8, 0, 0, 0.9) !important;
    border-right: 1px solid rgba(120, 40, 40, 0.35) !important;
}

/* Main panels */
.section,
.card,
.content,
.container-main,
.games-list-container,
.game-card-container {
    background: rgba(25, 5, 5, 0.85) !important;
    border: 1px solid rgba(140, 60, 60, 0.25) !important;
}

/* Search bar */
input {
    background: rgba(30, 0, 0, 0.75) !important;
    border: 1px solid rgba(160, 80, 80, 0.35) !important;
    color: #ffe0e0 !important;
    border-radius: 20px !important;
}

/* Buttons */
button,
.btn-primary,
.btn-secondary {
    background: rgba(60, 20, 20, 0.85) !important;
    border: 1px solid rgba(160, 80, 80, 0.4) !important;
    color: #ffe6e6 !important;
}

/* Button hover */
button:hover,
.btn-primary:hover {
    background: rgba(80, 25, 25, 0.95) !important;
}

/* Links */
a {
    color: #d8a0a0 !important;
}

a:hover {
    color: #ffe0e0 !important;
}

/* Friend avatars */
.avatar,
.avatar-card {
    border: 1px solid rgba(150, 70, 70, 0.35) !important;
}
}
